cd /tmp && rm -rf /tmp/mainchk && mkdir -p /tmp/mainchk && cd /tmp/shurik-workspace-nWd66L && git archive origin/main S01 S02 S03 S04 S05 | tar -x -C /tmp/mainchk && cd /tmp/mainchk && python3 - <<'EOF'
import re, yaml, pathlib
for p in sorted(pathlib.Path('.').glob('S*/E*.md')):
    text=p.read_text()
    parts=re.split(r"^---\s*$", text, maxsplit=2, flags=re.MULTILINE)
    ok = len(parts)==3 and not parts[0].strip()
    meta=yaml.safe_load(parts[1]) if ok else {}
    issues=[]
    if not ok: issues.append('frontmatter')
    else:
        if not str(meta.get('title','')).lower().startswith('the one with '): issues.append('title')
        if 'summary' not in meta: issues.append('summary')
        if not meta.get('summary','').strip(): issues.append('empty summary')
        body=parts[2].strip()
        if not body.startswith(meta.get('summary','')[:40]): issues.append('intro paragraph mismatch')
    print(p, meta.get('status'), issues if issues else 'OK')
EOF
